unsigned char sk[/*XMSS_OID_LEN + params.sk_bytes=136*/]={0x00,0x00,0x00,0x01,0x00,0x00,0x00,0x00,0x48,0x8e,0x41,0x29,0xa8,0x42,0x7f,0x59,0xf3,0xb1,0x23,0x03,0x46,0x4e,0x38,0x8a,0xce,0xb8,0x8e,0x1c,0x5f,0x20,0xa5,0xa5,0x21,0x7f,0x6f,0xcb,0x28,0xfc,0xfb,0xf9,0xce,0x12,0xd7,0xfd,0x36,0x15,0xc9,0x2c,0xdc,0x61,0xeb,0x74,0x01,0x5a,0xb1,0x4d,0x9e,0x6c,0x73,0x69,0xc5,0xef,0x77,0x19,0xfb,0x74,0xaf,0x47,0x53,0xea,0xcf,0x49,0x43,0xa5,0x37,0xf2,0x2c,0x33,0xe6,0x6d,0x23,0x5e,0x03,0x2e,0xaf,0x1d,0xf5,0x3b,0xcf,0xbe,0xc8,0x09,0xc0,0x9f,0x54,0x9c,0x0c,0x1f,0x84,0xf8,0x36,0xdf,0x9e,0x82,0xee,0xb6,0xd0,0xc3,0x11,0x5f,0x6d,0x0e,0x35,0x4c,0x44,0x97,0x98,0x20,0xb8,0x7a,0x96,0xc4,0x03,0xea,0x36,0x76,0xcc,0x73,0x12,0x23,0xd9,0x01,0x2b,0x62,0xdb,0x79,};

unsigned char *mout[2532];

int main()
{
  uint64_t cycles;
  clock_t tick;
  clock_t t0;
  uint64_t c0;

    xmss_params params;
    uint32_t oid;
    int ret = 0;
    int i,j;

    // TODO test more different variants
    XMSS_STR_TO_OID(&oid, XMSS_VARIANT);
    XMSS_PARSE_OID(&params, oid);

    //    unsigned char *m = malloc(XMSS_MLEN);
    
    //unsigned char *sm = malloc(params.sig_bytes + XMSS_MLEN);

    //    unsigned char *mout = malloc(params.sig_bytes + XMSS_MLEN);
    unsigned long long smlen;
    unsigned long long mlen;
    int rc;
    printf("hca...\n");
    rc = sifive_hca_plat_get(0, &_hca_dev);
    if (rc) {
      printf("Unable to get the HCA device\n");
      return rc;
    }
    hca_sha256_initialization();
    printf("SHA256 test\n");
    test_sha256();

    printf("XMSS test\n");
    //    randombytes(m, XMSS_MLEN);

    t0 = clock();
    c0 = riscv_read_mcycle();

    //    XMSS_KEYPAIR(pk, sk, oid);
    cycles = riscv_read_mcycle() - c0;
    tick = clock() - t0;
    printf("skey %d: ",XMSS_OID_LEN + params.sk_bytes);
    printf("%02x %02x.. %02x %02x\n",sk[0],sk[1],sk[XMSS_OID_LEN + params.sk_bytes-2],sk[XMSS_OID_LEN + params.sk_bytes-1]);
    /*    printf("skey: ");
    for(j=0;j<XMSS_OID_LEN + params.sk_bytes;j++)
      printf("%02x ",sk[j]);
      printf("\n");*/
    printf("pkey %d: ",XMSS_OID_LEN + params.pk_bytes);
    printf("%02x %02x.. %02x %02x\n",pk[0],pk[1],pk[XMSS_OID_LEN + params.pk_bytes-2],pk[XMSS_OID_LEN + params.pk_bytes-1]);
    /*    for(j=0;j<XMSS_OID_LEN + params.pk_bytes;j++)
      printf("%02x ",pk[j]);
      printf("\n");*/

    printf("XMSS keypair generation: cycles: %" PRIu64 "  ticks:  %lu\n", cycles, tick);

    printf("Testing %d %s signature", XMSS_SIGNATURES, XMSS_VARIANT);
    if(1<XMSS_SIGNATURES)
      printf("s");
    printf("..\n");
    for (i = 0; i < XMSS_SIGNATURES; i++) {
        printf("  - iteration #%d:\n", i);

	printf("signature computation\n");
	t0 = clock();
	c0 = riscv_read_mcycle();
	//        XMSS_SIGN(sk, sm, &smlen, m, XMSS_MLEN);
	smlen=params.sig_bytes + XMSS_MLEN;
	cycles = riscv_read_mcycle() - c0;
	tick = clock() - t0;
	printf("XMSS signature generation: cycles: %" PRIu64 "  ticks:  %lu\n", cycles, tick);

        if (smlen != params.sig_bytes + XMSS_MLEN) {
            printf("  X smlen incorrect [%llu != %u]!\n",
                   smlen, params.sig_bytes);
            ret = -1;
        }
        else {
            printf("    smlen as expected [%llu].\n", smlen);
        }
	printf("signature (%d bytes): ",params.sig_bytes + XMSS_MLEN);
	printf("%02x %02x .. %02x %02x\n",sm[0],sm[1],sm[params.sig_bytes + XMSS_MLEN-2],sm[params.sig_bytes + XMSS_MLEN-1]);
	/*	for(j=0;j<params.sig_bytes + XMSS_MLEN;j++)
	  printf("%02x ",sm[j]);
	  printf("\n");*/
	printf("signature verification\n");
	t0 = clock();
	c0 = riscv_read_mcycle();

        /* Test if signature is valid. */
        if (XMSS_SIGN_OPEN(mout, &mlen, sm, smlen, pk)) {
            printf("  X verification failed!\n");
            ret = -1;
        }
        else {
            printf("    verification succeeded.\n");
        }

	cycles = riscv_read_mcycle() - c0;
	tick = clock() - t0;
	printf("XMSS signature verification: cycles: %" PRIu64 "  ticks:  %lu\n", cycles, tick);

        /* Test if the correct message was recovered. */
        if (mlen != XMSS_MLEN) {
            printf("  X mlen incorrect [%llu != %u]!\n", mlen, XMSS_MLEN);
            ret = -1;
        }
        else {
            printf("    mlen as expected [%llu].\n", mlen);
        }
        if (memcmp(m, mout, XMSS_MLEN)) {
            printf("  X output message incorrect!\n");
            ret = -1;
        }
        else {
            printf("    output message as expected.\n");
        }

        /* Test if flipping bits invalidates the signature (it should). */

        /* Flip the first bit of the message. Should invalidate. */
        sm[smlen - 1] ^= 1;
        if (!XMSS_SIGN_OPEN(mout, &mlen, sm, smlen, pk)) {
            printf("  X flipping a bit of m DID NOT invalidate signature!\n");
            ret = -1;
        }
        else {
            printf("    flipping a bit of m invalidates signature.\n");
        }
        sm[smlen - 1] ^= 1;

#ifdef XMSS_TEST_INVALIDSIG
        int j;
        /* Flip one bit per hash; the signature is almost entirely hashes.
           This also flips a bit in the index, which is also a useful test. */
        for (j = 0; j < (int)(smlen - XMSS_MLEN); j += params.n) {
            sm[j] ^= 1;
            if (!XMSS_SIGN_OPEN(mout, &mlen, sm, smlen, pk)) {
                printf("  X flipping bit %d DID NOT invalidate sig + m!\n", j);
                sm[j] ^= 1;
                ret = -1;
                break;
            }
            sm[j] ^= 1;
        }
        if (j >= (int)(smlen - XMSS_MLEN)) {
            printf("    changing any signature hash invalidates signature.\n");
        }
#endif
    }

    //    free(m);
    //    free(sm);
    //free(mout);

    return ret;
}
